#include <iostream>
#include <typeinfo>

class A { public: int a; virtual void f() { std::cout << "A::f()\n"; } };
class B : virtual public A { public: int b; virtual void f() { std::cout << "B::f()\n"; } };
class C : virtual public A { public: int c; virtual void f() { std::cout << "C::f()\n"; } };
class D : public B, public C { public: int d; };
int main() {
  D d; d.f(); //Illustrates the virtual function dispatch mechanism in the context of virtual inheritance.
  std::cout << typeid(d).name() << std::endl; // Observe the type information
  return 0;
}
